import React, { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import emptyImg from 'assets/images/face_with_sweat.webp';

import styles from './NoResults.module.scss';

interface INoResultsProps extends HTMLAttributes<HTMLDivElement> {
	text?: string;
	subtext?: string;
	goTo?: React.ReactNode;
}

export const NoResults: FC<INoResultsProps> = ({ className, goTo, text, subtext, ...props }) => {
	const { t } = useTranslation();

	return (
		<div {...props} className={cn(className, styles.noResults)}>
			<img src={emptyImg} width={55} height={52} alt={text} />
			<Typography.Title level={3}>{text || t('No results')}</Typography.Title>
			{!!subtext && <Typography.Paragraph>{subtext}</Typography.Paragraph>}
			{!!goTo && goTo}
		</div>
	);
};
